#!/bin/bash
set -euo pipefail
ROOT_DIR="$(pwd)"
BUILD_DIR="${ROOT_DIR}/build"
SRC_DIR="${ROOT_DIR}/src"
LIB_DIR="${BUILD_DIR}/lib"
BIN_DIR="${BUILD_DIR}/bin"
HW_DIR="${BUILD_DIR}/hardware"
VER_DIR="${BUILD_DIR}/verification"
ZK_DIR="${BUILD_DIR}/zk"
mkdir -p "${LIB_DIR}" "${BIN_DIR}" "${HW_DIR}" "${VER_DIR}" "${ZK_DIR}"
echo "--- Phase 1: Tokenizers ---"
gleam build --target erlang "${SRC_DIR}/tokenizer" -o "${LIB_DIR}/gleam_tokenizer"
zig build-lib -O ReleaseFast -fPIC -dynamic --name p_adic_zig -lc "${SRC_DIR}/tokenizer/p_adic_tokenizer.zig" -o "${LIB_DIR}/libp_adic_zig.so"
julia -e 'using Pkg; Pkg.activate("src/tokenizer"); include("p_adic_tokenizer.jl"); println("Julia tokenizer ready")'
echo "--- Phase 2: GPU Kernels ---"
futhark opencl "${SRC_DIR}/gpu/ntt_mix.fut" -o "${LIB_DIR}/ntt_mix" -l "${LIB_DIR}/libntt_mix.so"
futhark opencl "${SRC_DIR}/gpu/fht_mix.fut" -o "${LIB_DIR}/fht_mix" -l "${LIB_DIR}/libfht_mix.so"
futhark opencl "${SRC_DIR}/gpu/wavelet_scattering.fut" -o "${LIB_DIR}/wavelet_scattering" -l "${LIB_DIR}/libwavelet_scattering.so"
echo "--- Phase 3: Core Zig Modules ---"
zig build-lib -O ReleaseFast -fPIC -dynamic -lc -lm -L"${LIB_DIR}" -lntt_mix -lfht_mix -lwavelet_scattering "${SRC_DIR}/core/ntt_mix.zig" -o "${LIB_DIR}/libntt_mix_zig.so"
zig build-lib -O ReleaseFast -fPIC -dynamic -lc -lm -L"${LIB_DIR}" -lntt_mix "${SRC_DIR}/core/fht_mix.zig" -o "${LIB_DIR}/libfht_mix_zig.so"
zig build-lib -O ReleaseFast -fPIC -dynamic -lc -lm -L"${LIB_DIR}" -lfht_mix "${SRC_DIR}/core/wavelet_conv.zig" -o "${LIB_DIR}/libwavelet_conv_zig.so"
zig build-lib -O ReleaseFast -fPIC -dynamic -lc -lm -L"${LIB_DIR}" -lwavelet_conv "${SRC_DIR}/core/kan_block.zig" -o "${LIB_DIR}/libkan_block_zig.so"
zig build-lib -O ReleaseFast -fPIC -dynamic -lc -lm -L"${LIB_DIR}" -lkan_block "${SRC_DIR}/core/factor_graph_solve.zig" -o "${LIB_DIR}/libfactor_graph_zig.so"
zig build-lib -O ReleaseFast -fPIC -dynamic --name jaide_v40_core -lc -lm -L"${LIB_DIR}" -lntt_mix_zig -lfht_mix_zig -lwavelet_conv_zig -lkan_block_zig -lfactor_graph_zig "${SRC_DIR}/core/main.zig" -o "${LIB_DIR}/libjaide_v40_core.so"
echo "--- Phase 4: Scientific Julia ---"
julia -e 'using Pkg; Pkg.activate("src/scientific"); Pkg.instantiate(); include("wavelet_scattering.jl"); precompute_scattering(); include("kan_param.jl"); generate_params(); include("chebyshev_filters.jl"); export_filters(); println("Julia scientific ready")'
echo "--- Phase 5: Distributed Chapel ---"
chpl "${SRC_DIR}/distributed/fractal_orchestrator.chpl" -o "${BIN_DIR}/fractal_orchestrator" --fast
echo "--- Phase 6: Hardware ---"
clash --verilog "${SRC_DIR}/hardware/FFToverlay.hs" -o "${HW_DIR}/FFToverlay.v"
sbt -Dsbt.global.base=src/hardware "runMain LongConvTop"
yosys -p "read_verilog ${HW_DIR}/FFToverlay.v; synth_ice40 -top FFToverlay -json ${HW_DIR}/fft_synth.json"
nextpnr-ice40 --hx8k --json "${HW_DIR}/fft_synth.json" --pcf "${SRC_DIR}/hardware/pins.pcf" --asc "${HW_DIR}/fft.asc"
icepack "${HW_DIR}/fft.asc" "${HW_DIR}/fft.bin"
echo "--- Phase 7: Formal Verification ---"
tlapm src/verification/pipeline.tla -o "${VER_DIR}/pipeline.tla.out"
lean "${SRC_DIR}/verification/kan_proofs.lean" --o="${VER_DIR}/kan_proofs.olean"
agda "${SRC_DIR}/verification/kan_types.agda" -o "${VER_DIR}/kan_types"
isabelle build -D "${SRC_DIR}/verification/isabelle" -o "${VER_DIR}/isabelle"
viper "${SRC_DIR}/verification/mem.vpr" -o "${VER_DIR}/mem.vpr.out"
vale build "${SRC_DIR}/verification/ipc_parser.vale" -o "${VER_DIR}/ipc_parser"
dedukti "${SRC_DIR}/verification/dedukti/weights.dk" -o "${VER_DIR}/weights.dk.out"
echo "--- Phase 8: Packaging ---"
cp "${LIB_DIR}"/* "${BUILD_DIR}/"
cp "${BIN_DIR}"/* "${BUILD_DIR}/"
cp "${HW_DIR}"/* "${BUILD_DIR}/"
cp "${VER_DIR}"/* "${BUILD_DIR}/"
echo "--- Build Complete ---"
