```gleam
pub fn p_adic_encode(text: String, base: Int, dim: Int) -> List(Int) {
  let chars = string.to_graphemes(text)
  let utf8_bytes = list.map(chars, fn(c) { string.to_utf8(c) })
  let normalized = list.flat_map(utf8_bytes, fn(bytes) {
    let bitplanes = extract_bitplanes(bytes, 8)
    let haar = haar_wavelet(bitplanes, 4)
    let walsh = walsh_hadamard(haar, dim)
    let sliced = bitplane_slice(walsh, base)
    let padded = polyphase_pad(sliced, 128000)
    padded
  })
  let batched = batch_stateless(normalized, 128000)
  batched
}

fn extract_bitplanes(bytes: List(Uint), levels: Int) -> List(List(Uint)) {
  list.map(0..levels, fn(level) {
    list.map(bytes, fn(b) { (b >> level) & 1 })
  })
}

fn haar_wavelet(data: List(List(Uint)), order: Int) -> List(List(Int)) {
  list.map(data, fn(plane) { haar_transform(plane, order) })
}

fn haar_transform(row: List(Uint), order: Int) -> List(Int) {
  let n = list.length(row)
  let padded_len = next_power_of_two(n)
  let padded = list.append(row, list.repeat(0u, padded_len - n))
  let levels = log2(padded_len)
  let mut transform = padded
  for level in 0..order {
    transform = haar_step(transform, 1 << (levels - level))
  }
  list.map(transform, int.from_uint)
}

fn haar_step(row: List(Int), step: Int) -> List(Int) {
  let n = list.length(row)
  let mut result = list.repeat(0, n)
  let mut i = 0
  while i < n {
    let mut j = 0
    while j < step {
      let idx1 = i + j
      let idx2 = idx1 + step
      if idx2 < n {
        let avg = (row[idx1] + row[idx2]) / 2
        let diff = (row[idx1] - row[idx2]) / 2
        result = list.set(result, idx1, avg)
        result = list.set(result, idx2, diff)
      } else {
        result = list.set(result, idx1, row[idx1])
      }
      j = j + 1
    }
    i = i + step * 2
  }
  result
}

fn next_power_of_two(n: Int) -> Int {
  let mut p = 1
  while p < n { p = p * 2 }
  p
}

fn log2(n: Int) -> Int {
  let mut l = 0
  let mut m = 1
  while m < n {
    m = m * 2
    l = l + 1
  }
  l
}

fn walsh_hadamard(data: List(List(Int)), dim: Int) -> List(List(Int)) {
  list.map(data, fn(row) { walsh_transform(row, dim) })
}

fn walsh_transform(row: List(Int), dim: Int) -> List(Int) {
  let n = list.length(row)
  let mut transform = list.append(row, list.repeat(0, next_power_of_two(n) - n))
  let logn = log2(n)
  for len in 1..logn + 1 {
    let block_size = 1 << len
    transform = walsh_inplace(transform, block_size)
  }
  list.take(transform, dim)
}

fn walsh_inplace(row: List(Int), block_size: Int) -> List(Int) {
  let n = list.length(row)
  let mut result = row
  let mut i = 0
  while i < n {
    let mut j = 0
    while j < block_size / 2 {
      let idx1 = i + j
      let idx2 = idx1 + block_size / 2
      if idx2 < n {
        let x1 = option.unwrap(list.get(result, idx1), 0)
        let x2 = option.unwrap(list.get(result, idx2), 0)
        result = list.set(result, idx1, (x1 + x2) / 2)
        result = list.set(result, idx2, (x1 - x2) / 2)
      }
      j = j + 1
    }
    i = i + block_size
  }
  result
}

fn bitplane_slice(data: List(List(Int)), base: Int) -> List(List(Int)) {
  list.map(data, fn(row) {
    let max_val = list.fold(row, 0, fn(acc, x) { max(acc, abs(x)) })
    let digits = log_base(max_val, base) + 1
    list.map(0..digits, fn(d) {
      list.map(row, fn(x) { (abs(x) / base.pow(d)) % base })
    })
  })
}

fn log_base(val: Int, base: Int) -> Int {
  let mut l = 0
  let mut p = 1
  while p < val {
    p = p * base
    l = l + 1
  }
  l - 1
}

fn polyphase_pad(data: List(List(Int)), block_size: Int) -> List(List(Int)) {
  list.map(data, fn(row) {
    let n = list.length(row)
    let phases = n % block_size
    list.append(row, list.repeat(0, block_size - phases))
  })
}

fn batch_stateless(data: List(List(Int)), block_size: Int) -> List(Int) {
  let mut flat = []
  for row in data {
    flat = list.append(flat, row)
  }
  flat
}

fn max(a: Int, b: Int) -> Int {
  if a > b { a } else { b }
}

fn abs(i: Int) -> Int {
  if i < 0 { -i } else { i }
}

pub fn p_adic_decode(tokens: List(Int), base: Int, dim: Int) -> String {
  let unbatched = unbatch_stateless(tokens, dim)
  let unpadded = list.map(unbatched, fn(row) { unpad_polyphase(row) })
  let unsliced = from_p_adic_digits(unpadded, base)
  let unwalsh = list.map(unsliced, fn(row) { inverse_walsh(row, dim) })
  let unhaar = list.map(unwalsh, fn(row) { inverse_haar(row) })
  let bitplanes = list.map(unhaar, fn(row) { reconstruct_bitplanes(row) })
  let bytes = list.flat_map(bitplanes, fn(planes) { from_bitplanes(planes) })
  let chars = from_utf8_bytes(bytes)
  string.concat(chars)
}

fn unbatch_stateless(data: List(Int), block_size: Int) -> List(List(Int)) {
  let num_blocks = data.len() / (block_size * block_size)
  list.map(0..num_blocks, fn(b) {
    let start = b * block_size * block_size
    list.slice(data, start, block_size * block_size)
  })
}

fn unpad_polyphase(row: List(Int)) -> List(Int) {
  list.take_while(row, fn(x) { x != 0 }, list.reverse(row)) |> list.reverse
}

fn from_p_adic_digits(rows: List(List(Int)), base: Int) -> List(List(Int)) {
  list.map(rows, fn(row) {
    let digits = list.transpose(row)
    list.map(digits, fn(dig) {
      list.fold(dig, 0, fn(acc, d, idx) { acc * base.pow(idx) + d })
    })
  })
}

fn inverse_walsh(data: List(List(Int)), dim: Int) -> List(List(Int)) {
  list.map(data, fn(row) { inverse_walsh_transform(row, dim) })
}

fn inverse_walsh_transform(row: List(Int), dim: Int) -> List(Int) {
  let n = list.length(row)
  let mut transform = list.append(row, list.repeat(0, next_power_of_two(n) - n))
  let logn = log2(n)
  for len in logn..0 {
    let block_size = 1 << len
    transform = inverse_walsh_inplace(transform, block_size)
  }
  list.take(transform, dim)
}

fn inverse_walsh_inplace(row: List(Int), block_size: Int) -> List(Int) {
  let n = list.length(row)
  let mut result = row
  let mut i = 0
  while i < n {
    let mut j = 0
    while j < block_size / 2 {
      let idx1 = i + j
      let idx2 = idx1 + block_size / 2
      if idx2 < n {
        let x1 = option.unwrap(list.get(result, idx1), 0)
        let x2 = option.unwrap(list.get(result, idx2), 0)
        result = list.set(result, idx1, x1 + x2)
        result = list.set(result, idx2, x1 - x2)
      }
      j = j + 1
    }
    i = i + block_size
  }
  result
}

fn inverse_haar(rows: List(List(Int))) -> List(List(Int)) {
  list.map(rows, fn(row) { inverse_haar_transform(row, 4) })
}

fn inverse_haar_transform(row: List(Int), order: Int) -> List(Int) {
  let n = list.length(row)
  let levels = log2(n)
  let mut transform = row
  for level in (levels - order)..levels {
    transform = inverse_haar_step(transform, 1 << level)
  }
  transform
}

fn inverse_haar_step(row: List(Int), step: Int) -> List(Int) {
  let n = list.length(row)
  let mut result = list.repeat(0, n)
  let mut i = 0
  while i < n {
    let mut j = 0
    while j < step {
      let idx1 = i + j
      let idx2 = idx1 + step
      if idx2 < n {
        let avg = option.unwrap(list.get(row, idx1), 0)
        let diff = option.unwrap(list.get(row, idx2), 0)
        result = list.set(result, idx1, avg + diff)
        result = list.set(result, idx2, avg - diff)
      } else {
        result = list.set(result, idx1, option.unwrap(list.get(row, idx1), 0))
      }
      j = j + 1
    }
    i = i + step * 2
  }
  result
}

fn reconstruct_bitplanes(rows: List(List(Int))) -> List(List(Uint)) {
  list.map(rows, fn(row) { list.map(row, uint.from_int) })
}

fn from_bitplanes(planes: List(List(Uint))) -> List(Uint) {
  let levels = list.length(planes)
  let n = list.length(list.at(planes, 0))
  list.map(0..n, fn(i) {
    list.fold(0..levels, 0u, fn(acc, level) {
      acc | (list.at(list.at(planes, level), i) << level)
    })
  })
}

fn from_utf8_bytes(bytes: List(Uint)) -> List(String) {
  let mut i = 0
  let mut chars = []
  let n = list.length(bytes)
  while i < n {
    let byte = list.at(bytes, i)
    if byte & 0b10000000 == 0 {
      chars = list.append(chars, string.from_utf8_byte(byte))
      i = i + 1
    } else if byte & 0b11100000 == 0b11000000 {
      if i + 1 >= n { break }
      let byte2 = list.at(bytes, i + 1)
      let char_code = ((byte & 0b00011111) << 6) | (byte2 & 0b00111111)
      chars = list.append(chars, string.from_utf8_code(char_code))
      i = i + 2
    } else if byte & 0b11110000 == 0b11100000 {
      if i + 2 >= n { break }
      let byte2 = list.at(bytes, i + 1)
      let byte3 = list.at(bytes, i + 2)
      let char_code = ((byte & 0b00001111) << 12) | ((byte2 & 0b00111111) << 6) | (byte3 & 0b00111111)
      chars = list.append(chars, string.from_utf8_code(char_code))
      i = i + 3
    } else if byte & 0b11111000 == 0b11110000 {
      if i + 3 >= n { break }
      let byte2 = list.at(bytes, i + 1)
      let byte3 = list.at(bytes, i + 2)
      let byte4 = list.at(bytes, i + 3)
      let char_code = ((byte & 0b00000111) << 18) | ((byte2 & 0b00111111) << 12) | ((byte3 & 0b00111111) << 6) | (byte4 & 0b00111111)
      chars = list.append(chars, string.from_utf8_code(char_code))
      i = i + 4
    } else {
      i = i + 1
    }
  }
  chars
}

pub type Tokenizer {
  Tokenizer(base: Int, dim: Int, block_size: Int)
}

pub fn new_tokenizer(base: Int, dim: Int, block_size: Int) -> Tokenizer {
  Tokenizer(base, dim, block_size)
}

pub fn encode(tokenizer: Tokenizer, text: String) -> List(Int) {
  p_adic_encode(text, tokenizer.base, tokenizer.dim)
}

pub fn decode(tokenizer: Tokenizer, tokens: List(Int)) -> String {
