const std = @import("std");
const math = std.math;
const mem = std.mem;
const testing = std.testing;
const Allocator = mem.Allocator;

const PAdicTokenizer = struct {
    base: u8,
    dim: usize,
    block_size: usize,
    allocator: Allocator,

    const Self = @This();

    pub fn init(allocator: Allocator, base: u8, dim: usize, block_size: usize) Self {
        return .{ .base = base, .dim = dim, .block_size = block_size, .allocator = allocator };
    }

    pub fn deinit(self: *Self) void {
        _ = self;
    }

    pub fn encode(self: *const Self, text: []const u8) ![]u32 {
        var gpa = std.heap.GeneralPurposeAllocator(.{}){ .backing_allocator = self.allocator };
        defer _ = gpa.deinit();
        var allocator = gpa.allocator();
        var lines = mem.split(u8, mem.trim(u8, text, " \t\n\r"), "\n");
        var normalized = std.ArrayList([]u8).init(allocator);
        defer normalized.deinit();
        while (lines.next()) |line| {
            var utf8_bytes = try allocator.alloc(u8, line.len * 4);
            var utf_len: usize = 0;
            var i: usize = 0;
            while (i < line.len) : (i += 1) {
                const c = line[i];
                if (c < 128) {
                    utf8_bytes[utf_len] = c;
                    utf_len += 1;
                } else if (c >= 192 and c < 224) {
                    if (i + 1 >= line.len) break;
                    utf8_bytes[utf_len] = c;
                    utf8_bytes[utf_len + 1] = line[i + 1];
                    utf_len += 2;
                    i += 1;
                } else if (c >= 224 and c < 240) {
                    if (i + 2 >= line.len) break;
                    utf8_bytes[utf_len] = c;
                    utf8_bytes[utf_len + 1] = line[i + 1];
                    utf8_bytes[utf_len + 2] = line[i + 2];
                    utf_len += 3;
                    i += 2;
                } else if (c >= 240 and c < 248) {
                    if (i + 3 >= line.len) break;
                    utf8_bytes[utf_len] = c;
                    utf8_bytes[utf_len + 1] = line[i + 1];
                    utf8_bytes[utf_len + 2] = line[i + 2];
                    utf8_bytes[utf_len + 3] = line[i + 3];
                    utf_len += 4;
                    i += 3;
                }
            }
            utf8_bytes.len = utf_len;
            try normalized.append(utf8_bytes);
        }
        var encoded = std.ArrayList(u32).init(allocator);
        defer encoded.deinit();
        for (normalized.items) |bytes| {
            var bitplanes = try self.extractBitplanes(allocator, bytes);
            defer for (bitplanes) |bp| allocator.free(bp);
            var haar = try self.haarWavelet(allocator, bitplanes);
            defer for (haar) |h| allocator.free(h);
            var walsh = try self.walshHadamard(allocator, haar, self.dim);
            defer for (walsh) |w| allocator.free(w);
            var sliced = try self.bitplaneSlice(allocator, walsh, self.base);
            defer for (sliced) |s| allocator.free(s);
            var padded = try self.polyphasePad(allocator, sliced, self.block_size);
            defer for (padded) |p| allocator.free(p);
            var flat = try self.flattenPadded(allocator, padded);
            defer allocator.free(flat);
            try encoded.appendSlice(flat);
