        return encoded.toOwnedSlice();
    }

    fn extractBitplanes(self: *const Self, allocator: Allocator, bytes: []const u8) ![][]u8 {
        const levels = 8;
        var bitplanes = try allocator.alloc([]u8, levels);
        for (bitplanes, 0..) |*bp, level| {
            bp.* = try allocator.alloc(u8, bytes.len);
            for (bytes, 0..) |b, i| {
                bp.*[i] = (b >> @intCast(level)) & 1;
            }
        }
        return bitplanes;
    }

    fn haarWavelet(self: *const Self, allocator: Allocator, bitplanes: [][]u8) ![][]i32 {
        const order = 4;
        var haar = try allocator.alloc([]i32, bitplanes.len);
        for (bitplanes, 0..) |plane, p| {
            var row = try allocator.alloc(i32, plane.len);
            for (plane, 0..) |b, i| {
                row[i] = @intCast(b);
            }
            var padded_len = self.nextPowerOfTwo(plane.len);
            var padded = try allocator.alloc(i32, padded_len);
            @memcpy(padded[0..plane.len], row);
            @memset(padded[plane.len..], 0);
            var transform = padded;
            var levels = self.log2(padded_len);
            for (0..order) |l| {
                const step = 1 << (levels - @as(u6, @intCast(l)));
                transform = try self.haarStep(allocator, transform, step);
            }
            haar[p] = transform;
            allocator.free(row);
        }
        return haar;
    }

    fn haarStep(self: *const Self, allocator: Allocator, row: []i32, step: usize) ![]i32 {
        var result = try allocator.alloc(i32, row.len);
        var i: usize = 0;
        while (i < row.len) : (i += step * 2) {
            var j: usize = 0;
            while (j < step) : (j += 1) {
                const idx1 = i + j;
                const idx2 = i + j + step;
                if (idx2 < row.len) {
                    const avg = (row[idx1] + row[idx2]) / 2;
                    const diff = (row[idx1] - row[idx2]) / 2;
                    result[idx1] = avg;
                    result[idx2] = diff;
                } else {
                    result[idx1] = row[idx1];
                }
            }
        }
        return result;
    }

    fn nextPowerOfTwo(self: *const Self, n: usize) usize {
        var p: usize = 1;
        while (p < n) p *= 2;
        return p;
    }

    fn log2(self: *const Self, n: usize) usize {
        var l: usize = 0;
        var m: usize = 1;
        while (m < n) {
            m *= 2;
            l += 1;
        }
        return l;
    }

    fn walshHadamard(self: *const Self, allocator: Allocator, haar: [][]i32, dim: usize) ![][]i32 {
        var walsh = try allocator.alloc([]i32, haar.len);
        for (haar, 0..) |hrow, idx| {
            var transform = try allocator.alloc(i32, hrow.len);
            @memcpy(transform, hrow);
            var n = hrow.len;
            var logn = self.log2(n);
            for (1..logn + 1) |len_log| {
                const block_size = 1 << len_log;
                transform = try self.walshInplace(allocator, transform, block_size);
            }
            if (transform.len > dim) {
                var trimmed = try allocator.alloc(i32, dim);
                @memcpy(trimmed, transform[0..dim]);
                allocator.free(transform);
                transform = trimmed;
            }
            walsh[idx] = transform;
        }
        return walsh;
    }

    fn walshInplace(self: *const Self, allocator: Allocator, row: []i32, block_size: usize) ![]i32 {
        var result = try allocator.alloc(i32, row.len);
        @memcpy(result, row);
        var n = row.len;
        var i: usize = 0;
        while (i < n) : (i += block_size) {
            var j: usize = 0;
            while (j < block_size / 2) : (j += 1) {
                const idx1 = i + j;
                const idx2 = i + j + block_size / 2;
                if (idx2 < n) {
                    const x1 = result[idx1];
                    const x2 = result[idx2];
                    result[idx1] = (x1 + x2) / 2;
                    result[idx2] = (x1 - x2) / 2;
                }
            }
        }
        return result;
    }

    fn bitplaneSlice(self: *const Self, allocator: Allocator, walsh: [][]i32, base: u8) ![][]u32 {
        var sliced = try allocator.alloc([]u32, walsh.len);
        for (walsh, 0..) |wrow, sidx| {
            var max_val: i32 = 0;
            for (wrow) |val| max_val = @max(max_val, @abs(val));
            const digits = self.logBase(@intCast(max_val), @as(usize, base)) + 1;
            var slice = try allocator.alloc([]u32, digits);
            for (0..digits) |d| {
                var dig_row = try allocator.alloc(u32, wrow.len);
                for (wrow, 0..) |val, vi| {
                    const abs_val = @abs(val);
                    dig_row[vi] = @intCast((abs_val / @as(i32, @intFromFloat(math.pow(@as(f32, @floatFromInt(base)), @floatFromInt(d))))) % @intCast(base));
                }
                slice[d] = dig_row;
            }
            sliced[sidx] = slice;
        }
        return sliced;
    }

    fn logBase(self: *const Self, val: i32, base: usize) usize {
        var l: usize = 0;
        var p: i32 = 1;
        while (p < val) {
            p *= @intCast(base);
            l += 1;
        }
        return l - 1;
    }

    fn polyphasePad(self: *const Self, allocator: Allocator, sliced: [][]u32, block_size: usize) ![][]u32 {
        var padded = try allocator.alloc([]u32, sliced.len);
        for (sliced, 0..) |sl, pidx| {
            var pad_row = try allocator.alloc([]u32, sl.len);
            for (sl, 0..) |dig, didx| {
                var row_len = dig.len;
                var phases = row_len % block_size;
                var p_row = try allocator.alloc(u32, row_len + phases);
                @memcpy(p_row[0..row_len], dig);
                @memset(p_row[row_len..], 0);
                pad_row[didx] = p_row;
            }
            padded[pidx] = pad_row;
        }
        return padded;
    }

    fn flattenPadded(self: *const Self, allocator: Allocator, padded: [][]u32) ![]u32 {
        var total_len: usize = 0;
        for (padded) |p| {
            for (p) |d| {
                total_len += d.len;
            }
        }
        var flat = try allocator.alloc(u32, total_len);
        var idx: usize = 0;
        for (padded) |p| {
            for (p) |d| {
                @memcpy(flat[idx..idx + d.len], d);
                idx += d.len;
            }
        }
        return flat;
    }

    pub fn decode(self: *const Self, tokens: []const u32) ![]u8 {
        var gpa = std.heap.GeneralPurposeAllocator(.{}){ .backing_allocator = self.allocator };
        defer _ = gpa.deinit();
        var allocator = gpa.allocator();
        var unbatched = try self.unbatchStateless(allocator, tokens);
        defer for (unbatched) |ub| allocator.free(ub);
        var unpadded = try self.unpadPolyphase(allocator, unbatched);
        defer for (unpadded) |up| allocator.free(up);
        var unsliced = try self.fromPAdicDigits(allocator, unpadded, self.base);
        defer for (unsliced) |us| allocator.free(us);
        var unwalsh = try self.inverseWalsh(allocator, unsliced, self.dim);
        defer for (unwalsh) |uw| allocator.free(uw);
        var unhaar = try self.inverseHaar(allocator, unwalsh);
        defer for (unhaar) |uh| allocator.free(uh);
        var bitplanes = try self.reconstructBitplanes(allocator, unhaar);
        defer for (bitplanes) |bp| allocator.free(bp);
        var bytes = try self.fromBitplanes(allocator, bitplanes);
        return bytes;
    }

    fn unbatchStateless(self: *const Self, allocator: Allocator, data: []const u32) ![][]u32 {
        const num_blocks = data.len / (self.block_size * self.block_size);
        var blocks = try allocator.alloc([]u32, num_blocks);
        for (0..num_blocks) |b| {
            const start = b * self.block_size * self.block_size;
            var block = try allocator.alloc(u32, self.block_size * self.block_size);
            @memcpy(block, data[start..start + block.len]);
            blocks[b] = block;
        }
        return blocks;
    }

    fn unpadPolyphase(self: *const Self, allocator: Allocator, batched: [][]u32) ![][]u32 {
        var unpadded = try allocator.alloc([]u32, batched.len);
        for (batched, 0..) |b, idx| {
            var up_row = try allocator.alloc([]u32, b.len);
            for (b, 0..) |row, ridx| {
                var non_zero = row.len;
                while (non_zero > 0 and row[non_zero - 1] == 0) {
                    non_zero -= 1;
                }
                var trimmed = try allocator.alloc(u32, non_zero);
                @memcpy(trimmed, row[0..non_zero]);
                up_row[ridx] = trimmed;
            }
            unpadded[idx] = up_row;
        }
        return unpadded;
    }

    fn fromPAdicDigits(self: *const Self, allocator: Allocator, rows: [][]u32, base: u8) ![][]i32 {
        var result = try allocator.alloc([]i32, rows.len);
        for (rows, 0..) |row, ridx| {
            var res_row = try allocator.alloc(i32, row[0].len);
            for (0..row.len) |didx| {
                var val: i32 = 0;
                for (0..row[didx].len) |vi| {
                    val += @intCast(row[didx][vi]) * @as(i32, math.pow(@as(f32, @floatFromInt(@intCast(base))), @floatFromInt(vi)));
                }
                res_row[didx] = val;
            }
            result[ridx] = res_row;
        }
        return result;
    }

    fn inverseWalsh(self: *const Self, allocator: Allocator, data: [][]i32, dim: usize) ![][]i32 {
        var inv_walsh = try allocator.alloc([]i32, data.len);
        for (data, 0..) |drow, i| {
            var transform = try allocator.alloc(i32, drow.len);
            @memcpy(transform, drow);
            var n = drow.len;
            var logn = self.log2(n);
            for (logn..0) |len_log| {
                const block_size = 1 << len_log;
                transform = try self.inverseWalshInplace(allocator, transform, block_size);
            }
            if (transform.len > dim) {
