                @memcpy(trimmed, transform[0..dim]);
                allocator.free(transform);
                transform = trimmed;
            }
            inv_walsh[i] = transform;
        }
        return inv_walsh;
    }

    fn inverseWalshInplace(self: *const Self, allocator: Allocator, row: []i32, block_size: usize) ![]i32 {
        var result = try allocator.alloc(i32, row.len);
        @memcpy(result, row);
        var n = row.len;
        var i: usize = 0;
        while (i < n) : (i += block_size) {
            var j: usize = 0;
            while (j < block_size / 2) : (j += 1) {
                const idx1 = i + j;
                const idx2 = i + j + block_size / 2;
                if (idx2 < n) {
                    const x1 = result[idx1];
                    const x2 = result[idx2];
                    result[idx1] = x1 + x2;
                    result[idx2] = x1 - x2;
                }
            }
        }
        return result;
    }

    fn inverseHaar(self: *const Self, allocator: Allocator, walsh: [][]i32) ![][]u8 {
        const order = 4;
        var inv_haar = try allocator.alloc([]u8, walsh.len);
        for (walsh, 0..) |wrow, hidx| {
            var transform = try allocator.alloc(i32, wrow.len);
            @memcpy(transform, wrow);
            var n = wrow.len;
            var levels = self.log2(n);
            for ((levels - order)..levels) |l| {
                const step = 1 << @as(u6, @intCast(l));
                transform = try self.inverseHaarStep(allocator, transform, step);
            }
            var bytes = try allocator.alloc(u8, transform.len);
            for (transform, 0..) |val, ti| {
                bytes[ti] = @intCast(@abs(val));
            }
            inv_haar[hidx] = bytes;
