        return inv_haar;
    }

    fn inverseHaarStep(self: *const Self, allocator: Allocator, row: []i32, step: usize) ![]i32 {
        var result = try allocator.alloc(i32, row.len);
        @memcpy(result, row);
        var i: usize = 0;
        while (i < row.len) : (i += step * 2) {
            var j: usize = 0;
            while (j < step) : (j += 1) {
                const idx1 = i + j;
                const idx2 = i + j + step;
                if (idx2 < row.len) {
                    const avg = result[idx1];
                    const diff = result[idx2];
                    result[idx1] = avg + diff;
                    result[idx2] = avg - diff;
                }
            }
        }
        return result;
    }

    fn reconstructBitplanes(self: *const Self, allocator: Allocator, haar: [][]u8) ![][]u8 {
        const levels = 8;
        var bitplanes = try allocator.alloc([]u8, levels);
        for (0..levels) |level| {
            var plane = try allocator.alloc(u8, haar.len);
            for (haar, 0..) |hrow, hi| {
