```julia
using LinearAlgebra
using FFTW
using Random
using Test

struct PAdicTokenizer
    base::Int
    dim::Int
    block_size::Int
end

function PAdicTokenizer(base=3, dim=18432, block_size=128000)
    PAdicTokenizer(base, dim, block_size)
end

function extract_bitplanes(bytes::Vector{UInt8}, levels::Int=8)
    n = length(bytes)
    bitplanes = [zeros(UInt8, n) for _ in 1:levels]
    for i in 1:n
        b = bytes[i]
        for level in 1:levels
            bitplanes[level][i] = (b >> (level-1)) & 0x01
        end
    end
    bitplanes
end

function haar_wavelet(data::Vector{Vector{UInt8}}, order::Int=4)
    haar = Vector{Vector{Int32}}()
    for plane in data
        n = length(plane)
        padded_len = nextpow(2, n)
        padded = vcat(plane, zeros(UInt8, padded_len - n))
        levels = log2(padded_len)
        transform = Int32.(padded)
        for l in 0:order-1
            step = 1 << Int(levels - l)
            transform = haar_step(transform, step)
        end
        push!(haar, transform)
    end
    haar
end

function haar_step(row::Vector{Int32}, step::Int)
    n = length(row)
    result = zeros(Int32, n)
    i = 1
    while i <= n
        j = 1
        while j <= step && i + step - 1 <= n
            idx1 = i + j - 1
            idx2 = idx1 + step
            if idx2 <= n
                avg = (row[idx1] + row[idx2]) ÷ 2
                diff = (row[idx1] - row[idx2]) ÷ 2
                result[idx1] = avg
                result[idx2] = diff
            else
                result[idx1] = row[idx1]
            end
            j += 1
        end
        i += step * 2
    end
    result
end

function walsh_hadamard(data::Vector{Vector{Int32}}, dim::Int)
    walsh = Vector{Vector{Int32}}()
    for row in data
        n = length(row)
        transform = copy(row)
        for len_log in 1:Int(log2(n))
            block_size = 1 << len_log
            transform = walsh_inplace(transform, block_size)
        end
        push!(walsh, transform[1:min(dim, length(transform))])
    end
    walsh
end

function walsh_inplace(row::Vector{Int32}, block_size::Int)
    n = length(row)
    result = copy(row)
    i = 1
    while i <= n
        j = 1
        while j <= block_size ÷ 2 && i + block_size - 1 <= n
            idx1 = i + j - 1
            idx2 = idx1 + block_size ÷ 2
            if idx2 <= n
                x1 = result[idx1]
                x2 = result[idx2]
                result[idx1] = (x1 + x2) ÷ 2
                result[idx2] = (x1 - x2) ÷ 2
            end
            j += 1
        end
        i += block_size
    end
    result
end

function bitplane_slice(data::Vector{Vector{Int32}}, base::Int)
    sliced = Vector{Vector{Vector{Int32}}}()
    for row in data
        max_val = maximum(abs.(row))
        digits = Int(floor(log(base, max_val))) + 1
        slice = [zeros(Int32, length(row)) for _ in 1:digits]
        for d in 0:digits-1
            for (vi, val) in enumerate(row)
                abs_val = abs(val)
                slice[d+1][vi] = (abs_val ÷ base^d) % base
            end
        end
        push!(sliced, slice)
    end
    sliced
end

function polyphase_pad(data::Vector{Vector{Vector{Int32}}}, block_size::Int)
    padded = Vector{Vector{Vector{Int32}}}()
    for slices in data
        pad_row = Vector{Vector{Int32}}()
        for dig in slices
            n = length(dig)
            phases = n % block_size
            p_row = vcat(dig, zeros(Int32, block_size - phases))
            push!(pad_row, p_row)
        end
        push!(padded, pad_row)
    end
    padded
end

function batch_stateless(data::Vector{Vector{Vector{Int32}}}, block_size::Int)
    flat = Int32[]
    for batch in data
        for row in batch
            append!(flat, row)
        end
    end
    flat
end

function p_adic_encode(tokenizer::PAdicTokenizer, text::String)
    utf8_bytes = codeunits(text)
    normalized = Vector{Vector{UInt8}}()
    for line in split(text, '\n')
        line_bytes = codeunits(strip(line))
        push!(normalized, collect(line_bytes))
    end
    bitplanes = [extract_bitplanes(bytes) for bytes in normalized]
    haar = [haar_wavelet(bp) for bp in bitplanes]
    walsh = [walsh_hadamard(h, tokenizer.dim) for h in haar]
    sliced = [bitplane_slice(w, tokenizer.base) for w in walsh]
    padded = [polyphase_pad(s, tokenizer.block_size) for s in sliced]
    batched = [batch_stateless(p, tokenizer.block_size) for p in padded]
    vcat(batched...)
end

function unbatch_stateless(data::Vector{Int32}, block_size::Int)
    num_blocks = length(data) ÷ (block_size * block_size)
    blocks = [data[(b-1)*block_size*block_size + 1 : b*block_size*block_size] for b in 1:num_blocks]
    blocks
end

function unpad_polyphase(batched::Vector{Vector{Int32}}, block_size::Int)
    unpadded = Vector{Vector{Vector{Int32}}}()
    for b in batched
        up_row = Vector{Vector{Int32}}()
        for row in b
            non_zero = findlast(!iszero, row)
            trimmed = non_zero !== nothing ? row[1:non_zero] : row
            push!(up_row, trimmed)
        end
        push!(unpadded, up_row)
    end
    unpadded
end

function from_p_adic_digits(rows::Vector{Vector{Vector{Int32}}}, base::Int)
    result = Vector{Vector{Int32}}()
    for row in rows
        res_row = zeros(Int32, length(row[1]))
        for didx in 1:length(row)
            dig = row[didx]
            for vi in 1:length(dig)
                res_row[vi] += dig[vi] * base^(didx-1)
            end
        end
        push!(result, res_row)
    end
    result
end

function inverse_walsh(data::Vector{Vector{Int32}}, dim::Int)
    inv_walsh = Vector{Vector{Int32}}()
    for drow in data
        n = length(drow)
        transform = copy(drow)
        logn = Int(log2(n))
        for len_log in logn:-1:1
            block_size = 1 << len_log
            transform = inverse_walsh_inplace(transform, block_size)
        end
        push!(inv_walsh, transform[1:min(dim, length(transform))])
    end
    inv_walsh
end

function inverse_walsh_inplace(row::Vector{Int32}, block_size::Int)
    n = length(row)
    result = copy(row)
    i = 1
    while i <= n
        j = 1
        while j <= block_size ÷ 2 && i + block_size - 1 <= n
            idx1 = i + j - 1
            idx2 = idx1 + block_size ÷ 2
            if idx2 <= n
                x1 = result[idx1]
                x2 = result[idx2]
                result[idx1] = x1 + x2
                result[idx2] = x1 - x2
            end
            j += 1
        end
        i += block_size
    end
    result
end

function inverse_haar(walsh::Vector{Vector{Int32}})
    order = 4
    inv_haar = Vector{Vector{UInt8}}()
    for wrow in walsh
        n = length(wrow)
        transform = copy(wrow)
        levels = Int(log2(n))
        for l in (levels - order + 1):levels
            step = 1 << l
            transform = inverse_haar_step(transform, step)
        end
        bytes = abs.(transform)
        push!(inv_haar, UInt8.(bytes))
    end
    inv_haar
end

function inverse_haar_step(row::Vector{Int32}, step::Int)
    n = length(row)
    result = zeros(Int32, n)
    i = 1
    while i <= n
        j = 1
        while j <= step && i + step - 1 <= n
            idx1 = i + j - 1
            idx2 = idx1 + step
            if idx2 <= n
                avg = row[idx1]
                diff = row[idx2]
                result[idx1] = avg + diff
                result[idx2] = avg - diff
            else
                result[idx1] = row[idx1]
            end
            j += 1
        end
        i += step * 2
    end
    result
end

function reconstruct_bitplanes(haar::Vector{Vector{UInt8}})
    levels = 8
    n = length(haar[1])
    bitplanes = [zeros(UInt8, n) for _ in 1:levels]
    for level in 1:levels
        for (hi, hrow) in enumerate(haar)
            if hi <= length(hrow)
                b = hrow[hi]
                bitplanes[level][hi] = (b >> (level-1)) & 0x01
            end
        end
    end
    bitplanes
end

function from_bitplanes(planes::Vector{Vector{UInt8}})
    levels = length(planes)
    n = length(planes[1])
    bytes = zeros(UInt8, n)
    for i in 1:n
        byte = 0
        for l in 1:levels
            if i <= length(planes[l])
                byte |= planes[l][i] << (l-1)
            end
        end
        bytes[i] = byte
    end
    bytes
end

function p_adic_decode(tokenizer::PAdicTokenizer, tokens::Vector{Int32})
    unbatched = unbatch_stateless(tokens, tokenizer.block_size)
    unpadded = unpad_polyphase(unbatched)
    unsliced = from_p_adic_digits(unpadded, tokenizer.base)
    unwalsh = inverse_walsh(unsliced, tokenizer.dim)
    unhaar = inverse_haar(unwalsh)
    bitplanes = reconstruct_bitplanes(unhaar)
    bytes = from_bitplanes(bitplanes)
    String(bytes)
end

function test_p_adic_tokenizer()
    tokenizer = PAdicTokenizer()
    text = "Hello World"
    encoded = p_adic_encode(tokenizer, text)
    decoded = p_adic_decode(tokenizer, encoded)
    @test decoded == text
end

function test_bitplanes()
    bytes = UInt8[65, 66, 67]
    bitplanes = extract_bitplanes(bytes)
    @test length(bitplanes) == 8
    @test all(length(bp) == 3 for bp in bitplanes)
end

function test_haar()
    plane = UInt8[1, 0, 1, 0]
    planes = [plane]
    haar = haar_wavelet(planes)
    @test length(haar) == 1
    @test length(haar[1]) == 4
end

function test_walsh()
    haar_row = Int32[1, -1, 1, -1]
