    padded = polyphase_pad(slice, 4)
    @test padded[1][1] == [1, 2, 0, 0]
end

function test_batch()
    p_row1 = Int32[1, 2, 0, 0]
    p_row2 = Int32[3, 4, 0, 0]
    padded = [ [p_row1], [p_row2] ]
