import "futhark/opencl"

-- Modular arithmetic
type mod = i64
let mod_add (m: i64) (a: mod) (b: mod): mod = (a + b) % m
let mod_sub (m: i64) (a: mod) (b: mod): mod = (a - b + m) % m
let mod_mul (m: i64) (a: mod) (b: mod): mod = (a * b) % m
let mod_pow (m: i64) (a: mod) (exp: i64): mod =
  loop res = 1 while exp > 0 do
    if exp % 2 == 1 then mod_mul m res a else res,
    a = mod_mul m a a,
    exp /= 2
  in res

-- Primitive root check
let is_primitive_root (m: i64) (omega: mod) (order: i64): bool =
  mod_pow m omega order == 1 &&
  all (fn k => mod_pow m omega k != 1) (1..order-1)

-- NTT kernel
entry ntt [n] (omega: mod) (m: i64) (vec: [n]i64): [n]mod =
  map (fn i =>
    let pow_omega = mod_pow m omega i
    in map (fn v => mod_mul m pow_omega v) vec
  ) (0..<n) |> transpose |> map (reduce (mod_add m) 0)

-- Cooley-Tukey radix-2
entry ntt_ct [n] (omega: mod) (m: i64) (vec: [n]i64): [n]mod =
  if n == 1 then map int64.i64 vec else
  let half = n / 2
  let even = vec[0::2]
  let odd = vec[1::2]
  let even_ntt = ntt_ct (mod_pow m omega 2) m even
  let odd_ntt = ntt_ct (mod_pow m omega 2) m odd
  let twiddles = map (mod_pow m omega) (0..<half)
  let added = map2 (mod_add m) even_ntt (map2 (mod_mul m) twiddles odd_ntt)
  let subed = map2 (mod_sub m) even_ntt (map2 (mod_mul m) twiddles odd_ntt)
  in added ++ subed

-- Inverse NTT
entry inv_ntt [n] (omega: mod) (m: i64) (vec: [n]mod): [n]i64 =
  let inv_omega = mod_pow m omega (m - 2)
  let ntt_inv = ntt_ct inv_omega m vec
  in map (fn v => (v % n).i64) ntt_inv

-- NTT mix kernel
entry ntt_mix [n] (omega: mod) (m: i64) (a: [n]i64) (b: [n]i64): [n]i64 =
  let a_ntt = ntt_ct omega m a
  let b_ntt = ntt_ct omega m b
  let prod = map2 (mod_mul m) a_ntt b_ntt
  in inv_ntt omega m prod

-- Batch NTT mix
entry batch_ntt_mix [batch][n] (omega: mod) (m: i64) (as: [batch][n]i64) (bs: [batch][n]i64): [batch][n]i64 =
  map2 (ntt_mix omega m) as bs

-- Primes and roots
let primes = [17, 257, 65537, 2**61 - 1]
let roots = [3, 3, 3, 10]  -- Primitive roots mod primes

-- Multi-prime NTT
entry multi_prime_ntt [n] (a: [n]i64) (b: [n]i64): [n]i64 =
  let mods = map2 (fn p r => ntt_mix r p a b) primes roots
  let crt = map (fn i => chinese_remainder mods[i] primes) (0..<length primes)
  in crt

let chinese_remainder (remainders: []i64) (moduli: []i64): i64 =
  let M = reduce (*) 1 moduli
  let sum = sum (map3 (fn r m i =>
    let Mi = M / m
    let yi = mod_inverse Mi m
    r * Mi * yi
  ) remainders moduli (iota (length moduli)))
  in sum % M

let mod_inverse (a: i64) (m: i64): i64 = mod_pow m a (euler_totient m - 1)

let euler_totient (n: i64): i64 =
  let factors = filter (fn p => n % p == 0) primes
  in n * product (map (fn p => 1 - 1/p) factors)

-- Parallel NTT
entry par_ntt [n] (omega: mod) (m: i64) (vec: [n]i64): [n]mod =
  let logn = i32.log2 n
  let bitrev = map (fn i => bitreverse i logn) (0..<n)
  let reordered = vec[bitrev]
  in loop reordered for s in 1..logn do
    let block = 1 << s
    let groups = n / block
    let tw_step = block / 2
    in map (fn g =>
      map (fn j =>
        let idx1 = g * block + j
        let idx2 = idx1 + tw_step
        let tw = mod_pow m omega (g * tw_step + j)
        let u = reordered[idx1]
        let v = mod_mul m tw reordered[idx2]
        in [u + v, u - v]
      ) (0..<tw_step)
    ) (0..<groups) |> flatten

-- Fractal instantiation
entry fractal_ntt [levels][n] (omega: mod) (m: i64) (vecs: [levels][n]i64): [levels][n]i64 =
  map (fn lvl => par_ntt omega m vecs[lvl]) (0..<levels)

-- Convolution NTT
entry conv_ntt [n] (omega: mod) (m: i64) (a: [n]i64) (b: [n]i64): [2*n-1]i64 =
  let padded_n = nextpow2 (2*n - 1)
  let padded_a = a ++ replicate (padded_n - n) 0
  let padded_b = b ++ replicate (padded_n - n) 0
  let a_ntt = par_ntt omega m padded_a
  let b_ntt = par_ntt omega m padded_b
  let prod = map2 (mod_mul m) a_ntt b_ntt
  let inv = inv_ntt omega m prod
  in take (2*n - 1) inv
