fn conv1d(allocator: Allocator, signal: []const f64, filter: []const f64, mode: enum { full, same, valid }) ![]f64 {
    const n = signal.len;
    const k = filter.len;
    const m = switch (mode) {
        .full => n + k - 1,
        .same => n,
        .valid => if (n >= k) n - k + 1 else 0,
    };
    var result = try allocator.alloc(f64, m);
    switch (mode) {
        .full => {
            for (0..m) |i| {
                var sum: f64 = 0.0;
                const start = @max(0, @as(isize, @intCast(i)) - @as(isize, @intCast(k - 1)));
                const end_ = @min(@as(isize, @intCast(i)) + 1, @as(isize, @intCast(n)));
                for (start..end_) |j| {
                    sum += signal[@intCast(j)] * filter[@intCast(i - j)];
                }
                result[i] = sum;
            }
        },
        .same => {
            const pad_left = k / 2;
            const pad_right = k - 1 - pad_left;
            var padded = try allocator.alloc(f64, n + pad_left + pad_right);
            defer allocator.free(padded);
            @memset(padded[0..pad_left], 0);
            @memcpy(padded[pad_left..pad_left + n], signal);
            @memset(padded[pad_left + n..], 0);
            var conv = try conv1d(allocator, padded, filter, .full);
            defer allocator.free(conv);
            @memcpy(result, conv[pad_left..pad_left + n]);
        },
        .valid => {
            if (n < k) {
                @memset(result, 0);
                return result;
            }
            for (0..m) |i| {
                var sum: f64 = 0.0;
                for (0..k) |j| {
                    sum += signal[i + j] * filter[j];
                }
                result[i] = sum;
            }
        },
    }
    return result;
}

fn modulus(allocator: Allocator, x: []const f64) ![]f64 {
    var res = try allocator.alloc(f64, x.len);
    for (0..x.len) |i| {
        res[i] = math.fabs(x[i]);
    }
    return res;
}

fn timeAvg(x: []const f64) f64 {
    var sum: f64 = 0.0;
    for (x) |val| {
        sum += val;
    }
    return sum / @as(f64, @floatFromInt(x.len));
}

fn morletWavelet(allocator: Allocator, sigma: f64, length: usize) !struct { coeffs: []f64, length: usize } {
    const center = length / 2;
    var coeffs = try allocator.alloc(f64, length);
    for (0..length) |i| {
        const t = @as(f64, @floatFromInt(@intCast(i - center))) / sigma;
        coeffs[i] = math.exp(-t * t / 2) * math.cos(2 * math.pi * t);
    }
    return .{ .coeffs = coeffs, .length = length };
}

fn waveletScattering(allocator: Allocator, signal: []const f64, J: usize, Q: usize) ![]f64 {
    const scales = 1 << J;
    var filters1 = try allocator.alloc([]f64, Q * scales);
    var filter_idx: usize = 0;
    for (0..Q) |q| {
        for (0..scales) |s| {
            const sigma = math.pow(f64, 2, @as(f64, @floatFromInt(q)) / @as(f64, @floatFromInt(Q)) + @as(f64, @floatFromInt(s)));
            var morlet_filter = try morletWavelet(allocator, sigma, 2 * J + 1);
            defer allocator.free(morlet_filter.coeffs);
            filters1[filter_idx] = try allocator.dupe(f64, morlet_filter.coeffs);
            filter_idx += 1;
        }
    }
    defer for (filters1) |f| allocator.free(f);
    var u1 = std.ArrayList(f64).init(allocator);
    defer u1.deinit();
    for (0..Q * scales) |fi| {
        var conv = try conv1d(allocator, signal, filters1[fi], .full);
        defer allocator.free(conv);
        var mod_conv = try modulus(allocator, conv);
        defer allocator.free(mod_conv);
        var avg = timeAvg(mod_conv);
        try u1.append(avg);
    }
    return u1.toOwnedSlice();
}

fn waveletMix(allocator: Allocator, a: []const f64, b: []const f64) ![]f64 {
    const n = a.len;
    if (b.len != n) return error.LengthMismatch;
    var a_scatter = try waveletScattering(allocator, a, 8, 12);
    defer allocator.free(a_scatter);
    var b_scatter = try waveletScattering(allocator, b, 8, 12);
    defer allocator.free(b_scatter);
    var mixed = try allocator.alloc(f64, a_scatter.len);
    for (0..a_scatter.len) |i| {
        mixed[i] = a_scatter[i] * b_scatter[i];
    }
    var recon = try conv1d(allocator, mixed, &[_]f64{1}, .full);  
    defer allocator.free(recon);
    return try allocator.dupe(f64, recon[0..n]);
}

fn batchWaveletMix(allocator: Allocator, batch_size: usize, a: [][]const f64, b: [][]const f64) ![][]f64 {
    if (a.len != batch_size or b.len != batch_size) return error.BatchMismatch;
    const n = a[0].len;
    var results = try allocator.alloc([]f64, batch_size);
    for (0..batch_size) |bi| {
        if (a[bi].len != n or b[bi].len != n) return error.LengthMismatch;
        results[bi] = try waveletMix(allocator, a[bi], b[bi]);
    }
    return results;
}

pub const WaveletConv = struct {
    allocator: Allocator,
    J: usize,
    Q: usize,

    const Self = @This();

    pub fn init(allocator: Allocator, J: usize, Q: usize) Self {
        return .{ .allocator = allocator, .J = J, .Q = Q };
    }

    pub fn deinit(self: *Self) void {
        _ = self;
    }

    pub fn conv(self: *Self, signal: []const f64) ![]f64 {
        return waveletScattering(self.allocator, signal, self.J, self.Q);
    }

    pub fn mix(self: *Self, a: []const f64, b: []const f64) ![]f64 {
        return waveletMix(self.allocator, a, b);
    }

    pub fn batchMix(self: *Self, a: [][]const f64, b: [][]const f64) ![][]f64 {
        return batchWaveletMix(self.allocator, a.len, a, b);
    }
};

test "morlet wavelet" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();
    var wavelet = try morletWavelet(allocator, 1.0, 5);
    defer allocator.free(wavelet.coeffs);
    try testing.expectEqual(@as(usize, 5), wavelet.length);
    try testing.expectApproxEqAbs(1.0, wavelet.coeffs[2], 1e-6);
}

test "conv1d full" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();
    const signal = [_]f64{ 1, 2, 3 };
    const filter = [_]f64{ 1, 0, -1 };
    var res = try conv1d(allocator, &signal, &filter, .full);
    defer allocator.free(res);
    try testing.expectApproxEqAbs(1.0, res[0], 1e-6);
    try testing.expectApproxEqAbs(1.0, res[1], 1e-6);
    try testing.expectApproxEqAbs(0.0, res[2], 1e-6);
    try testing.expectApproxEqAbs(-3.0, res[3], 1e-6);
    try testing.expectApproxEqAbs(-3.0, res[4], 1e-6);
}

test "conv1d same" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();
    const signal = [_]f64{ 1, 2, 3 };
