method encode(text: String, base: int, dim: int) returns (tokens: Seq[int])
  requires base > 1 && base <= 10
  requires dim > 0
  ensures |tokens| == expected_length(text, base, dim)
{
  var chars: Seq[String] := to_graphemes(text)
  var utf8_bytes: Seq[Seq[int]] := map(chars, c => to_utf8(c))
  var normalized: Seq[Seq[int]] := flat_map(utf8_bytes, bytes => process_bytes(bytes, base))
  var batched: Seq[int] := batch(normalized, dim)
  return batched
}

method process_bytes(bytes: Seq[int], base: int) returns (processed: Seq[Seq[int]])
  requires forall i :: 0 <= i < |bytes| ==> 0 <= bytes[i] < 256
  ensures |processed| == 8 * |bytes|
{
  var bitplanes: Seq[Seq[int]] := map(0..7, level => map(bytes, b => (b >> level) & 1))
  var haar: Seq[Seq[int]] := map(bitplanes, plane => haar_transform(plane, 4))
  var walsh: Seq[Seq[int]] := map(haar, row => walsh_transform(row, dim))
  var sliced: Seq[Seq[Seq[int]]] := map(walsh, row => p_adic_slice(row, base))
  processed := flat_map(sliced, s => pad(s, 128000))
}

method haar_transform(plane: Seq[int], order: int) returns (transformed: Seq[int])
  requires forall i :: 0 <= i < |plane| ==> plane[i] == 0 || plane[i] == 1
  ensures |transformed| == next_power_two(|plane|)
{
  var n := |plane|
  var padded_len := next_power_two(n)
  var padded: Seq[int] := append(plane, replicate(padded_len - n, 0))
  var levels := log2(padded_len)
  var t := padded
  for level in 0..order {
    t := haar_step(t, 1 << (levels - level))
  }
  transformed := t
}

method haar_step(row: Seq[int], step: int) returns (result: Seq[int])
  requires |row| % (step * 2) == 0
  ensures forall i :: 0 <= i < |row| ==> result[i] >= -1000 && result[i] <= 1000
{
  var n := |row|
  result := replicate(n, 0)
  var i := 0
  while i < n {
    var j := 0
    while j < step {
      var idx1 := i + j
      var idx2 := idx1 + step
      if idx2 < n {
        var avg := (row[idx1] + row[idx2]) / 2
        var diff := (row[idx1] - row[idx2]) / 2
        result[idx1] := avg
        result[idx2] := diff
      } else {
        result[idx1] := row[idx1]
      }
      j := j + 1
    }
    i := i + step * 2
  }
}

method walsh_transform(row: Seq[int], dim: int) returns (transformed: Seq[int])
  requires |row| <= dim * 2
  ensures |transformed| == dim
{
  var n := |row|
  var t := append(row, replicate(next_power_two(n) - n, 0))
  var logn := log2(n)
  for len in 1..logn + 1 {
    var block_size := 1 << len
    t := walsh_inplace(t, block_size)
  }
  transformed := take(t, dim)
}

method walsh_inplace(row: Seq[int], block_size: int) returns (result: Seq[int])
  requires |row| % block_size == 0
{
  var n := |row|
  result := copy(row)
  var i := 0
  while i < n {
    var j := 0
    while j < block_size / 2 {
      var idx1 := i + j
      var idx2 := idx1 + block_size / 2
      if idx2 < n {
        var x1 := result[idx1]
        var x2 := result[idx2]
        result[idx1] := (x1 + x2) / 2
        result[idx2] := (x1 - x2) / 2
      }
      j := j + 1
    }
    i := i + block_size
  }
}

-- Similar methods for p_adic_slice, pad, batch, etc., with appropriate specs
method p_adic_slice(row: Seq[int], base: int) returns (sliced: Seq[Seq[int]])
  requires base > 1
  ensures forall s in sliced :: |s| == |row|
{
  var max_val := fold(row, 0, max)
  var digits := floor(log_base(max_val, base)) + 1
  sliced := map(0..digits, d => map(row, x => (abs(x) / base^d) % base))
}

method batch(data: Seq[Seq[int]], block_size: int) returns (batched: Seq[int])
  ensures |batched| == |flat_map(data, id)|
{
  batched := flat_map(data, id)
}

-- Memory safety
method safe_alloc(size: int) returns (mem: Ref)
  requires size >= 0
  ensures allocated(mem, size)
{
  mem := new(Seq[int](size))
}
